actions.script:
import org.moqui.resource.ResourceReference

String targetUri = uri.trim()
String textContent = null
String mimeType = "text/plain"
Map metadata = [:]

def resolveMimeType = { String location ->
    if (location.endsWith('.xml')) return 'application/xml'
    if (location.endsWith('.json')) return 'application/json'
    if (location.endsWith('.md')) return 'text/markdown'
    if (location.endsWith('.groovy')) return 'text/x-groovy'
    if (location.endsWith('.qvt.js')) return 'application/javascript'
    return 'text/plain'
}

// 1. Check DB WikiPage if URI points to intent/ or discussion/
if (targetUri.contains('/resources/intent/') || targetUri.contains('/resources/discussion/')) {
    String pagePath = targetUri.replaceAll('^mcp://[^/]+/resources/', '')
    try {
        def wikiPage = ec.entity.find("moqui.resource.wiki.WikiPage")
            .condition("pagePath", pagePath)
            .one()
        if (wikiPage != null) {
            def history = ec.entity.find("moqui.resource.wiki.WikiPageHistory")
                .condition("wikiPageId", wikiPage.wikiPageId)
                .orderBy("-historySequenceNum")
                .list()
            if (history) {
                textContent = history[0].content
                mimeType = "text/markdown"
                metadata.wikiPageId = wikiPage.wikiPageId
                metadata.version = history[0].versionName ?: history[0].historySequenceNum
            }
        }
    } catch (Exception e) {
        ec.logger.warn("⚠️ [get#ResourceContent] WikiPage resolution error: ${e.message}")
    }
}

// 2. Fallback to physical filesystem under <comp>/mcp/resources/
if (textContent == null && targetUri.startsWith("mcp://")) {
    String subPath = targetUri.substring(6) // Remove "mcp://"
    int slashIdx = subPath.indexOf('/')
    if (slashIdx > 0) {
        String compName = subPath.substring(0, slashIdx)
        String filePath = subPath.substring(slashIdx + 1) // e.g. "resources/screen/archetype/lookup-modal.xml"
        String compLocation = "component://${compName}/mcp/${filePath}"

        ResourceReference rr = ec.resource.getLocationReference(compLocation)
        if (rr != null && rr.exists) {
            textContent = rr.getText()
            mimeType = resolveMimeType(compLocation)
            metadata.location = compLocation
            metadata.component = compName
            metadata.lastModified = rr.getLastModified()
        }
    }
}

// 3. Attach DB Facets if available
try {
    def facets = ec.entity.find("org.moqui.ai.mcp.McpResourceFacet")
        .condition("resourceUri", targetUri)
        .list()
    facets.each { f -> metadata[f.facetKey] = f.facetValue }
} catch (Exception ignored) {}

if (textContent != null) {
    context.uri = targetUri
    context.contents = [[
        uri: targetUri,
        mimeType: mimeType,
        text: textContent
    ]]
    context.metadata = metadata
    context.status = "SUCCESS"
    ec.logger.info("📖 [get#ResourceContent] Successfully resolved MCP resource: ${targetUri}")
} else {
    context.uri = targetUri
    context.contents = []
    context.metadata = [:]
    context.status = "NOT_FOUND"
    ec.logger.warn("❌ [get#ResourceContent] Resource not found for URI: ${targetUri}")
}
